-- Unified expense app: PostgreSQL 16 schema (plan; generated by Django migrations at implementation).
-- Money: bigint minor units + ISO 4217 currency. Timestamps: timestamptz (UTC).
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE app_user (
  id uuid PRIMARY KEY,
  email citext NOT NULL UNIQUE,
  password_hash text NOT NULL,
  email_verified_at timestamptz,
  display_name text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE budget (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  limit_minor bigint NOT NULL CHECK (limit_minor > 0),
  currency char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  time_zone text NOT NULL,
  owner_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX budget_owner_idx ON budget(owner_id);

CREATE TABLE membership (
  id uuid PRIMARY KEY,
  budget_id uuid NOT NULL REFERENCES budget(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('owner', 'member')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz,
  UNIQUE (budget_id, user_id),
  CHECK (NOT (role = 'owner' AND removed_at IS NOT NULL))
);
CREATE INDEX membership_user_idx ON membership(user_id);
CREATE UNIQUE INDEX one_owner_per_budget ON membership(budget_id) WHERE role = 'owner';

CREATE TABLE invitation (
  id uuid PRIMARY KEY,
  budget_id uuid NOT NULL REFERENCES budget(id) ON DELETE CASCADE,
  email citext NOT NULL,
  token_hash text NOT NULL UNIQUE,
  invited_by uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  accepted_at timestamptz,
  revoked_at timestamptz
);
CREATE INDEX invitation_budget_idx ON invitation(budget_id);
CREATE INDEX invitation_invited_by_idx ON invitation(invited_by);
CREATE UNIQUE INDEX one_pending_invite ON invitation(budget_id, email) WHERE accepted_at IS NULL AND revoked_at IS NULL;

CREATE TABLE receipt (
  id uuid PRIMARY KEY,
  uploaded_by uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  storage_key text NOT NULL UNIQUE,
  content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/heic', 'application/pdf')),
  size_bytes integer NOT NULL CHECK (size_bytes > 0),
  status text NOT NULL CHECK (status IN ('uploaded', 'read', 'failed', 'confirmed')),
  ocr_provider text,
  extracted_merchant text,
  extracted_date date,
  extracted_total_minor bigint,
  extracted_currency char(3),
  date_flagged boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX receipt_uploaded_by_idx ON receipt(uploaded_by);
CREATE INDEX receipt_status_created_idx ON receipt(status, created_at);

CREATE TABLE expense (
  id uuid PRIMARY KEY,
  author_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
  budget_id uuid REFERENCES budget(id) ON DELETE CASCADE,
  amount_minor bigint NOT NULL CHECK (amount_minor > 0 AND amount_minor <= 100000000000),
  currency char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  spent_on date NOT NULL,
  merchant text NOT NULL DEFAULT '' CHECK (length(merchant) <= 200),
  category text NOT NULL CHECK (category IN ('food', 'travel', 'home', 'other')),
  note text NOT NULL DEFAULT '' CHECK (length(note) <= 1000),
  receipt_id uuid UNIQUE REFERENCES receipt(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX expense_author_spent_idx ON expense(author_id, spent_on DESC);
CREATE INDEX expense_budget_spent_idx ON expense(budget_id, spent_on DESC);
CREATE INDEX expense_category_idx ON expense(category);
-- Budget currency match (expense.currency = budget.currency when budget_id is set) is enforced in the expenses module
-- inside the same transaction; a trigger can be added if a second writer ever appears.
